  });

  const [status, setStatus] = useState('idle'); // idle | pending | success | error | registering
  const [errorMsg, setErrorMsg] = useState('');
  const [syncStep, setSyncStep] = useState('idle'); // idle, preparing, awaiting_signature, indexing, confirmed
  const [generatedId, setGeneratedId] = useState('');
  const [txHash, setTxHash] = useState('');
  const [authorizedPatients, setAuthorizedPatients] = useState([]);
  const [loadingPatients, setLoadingPatients] = useState(false);
  const [pendingAppointments, setPendingAppointments] = useState([]);
  const [loadingPending, setLoadingPending] = useState(false);
  const [isFromPending, setIsFromPending] = useState(false);
  const [myConsultations, setMyConsultations] = useState([]);
  const [loadingConsultations, setLoadingConsultations] = useState(false);

  React.useEffect(() => {
    if (stellarAddress) {
      fetchPatients();
      fetchPendingAppointments();
      fetchConsultations();
    }
  }, [stellarAddress]);

  const fetchConsultations = async () => {
    try {
      setLoadingConsultations(true);
      const data = await dbService.getConsultationsByDoctor(stellarAddress);
      setMyConsultations(data || []);
    } catch (e) {
      console.warn('Failed to fetch consultations', e);
    } finally {
      setLoadingConsultations(false);
    }
  };

  const fetchPendingAppointments = async () => {
    try {
      setLoadingPending(true);
      const data = await dbService.getPendingAppointments(stellarAddress);
      const addrs = data.map(a => a.patient_wallet || a.patient).filter(Boolean);
      setPendingAppointments([...new Set(addrs)]);
    } catch (e) {
      console.warn('Failed to fetch pending', e);
    } finally {
      setLoadingPending(false);
    }
  };

  const fetchPatients = async () => {
    try {
      setLoadingPatients(true);
      const data = await dbService.getAuthorizedPatients(stellarAddress);
      setAuthorizedPatients([...new Set(data)].filter(Boolean));
    } catch (e) {
      console.warn('Failed to fetch patients', e);
    } finally {
      setLoadingPatients(false);
    }
  };

  // 1. Instant Clinical Issuance (Bypasses wallet for Demo flow as requested)
  const prepareAndSubmit = async (e) => {
    e.preventDefault();
    if (!stellarAddress) return alert("Please connect Freighter wallet");

    try {
      setStatus('pending');
      setErrorMsg('');

      // Step A: Instant Hashing
      const hash = await generateHash(formData);

      // Step B: Direct Local State Sync (Bypassing Wallet Popup)
      console.log("Preparing instant ledger synchronization...");
      setStatus('generating_proof');

      // Mocking the indexing delay for a "premium" feel
      await new Promise(r => setTimeout(r, 800));

      // Step C: Update Local History & Consultations
      await dbService.insertConsultation({
        doctor_wallet: stellarAddress,
        patient_wallet: formData.patientAddr,
        prescription_id: hash,
        medication: formData.medicines,
        diagnosis: formData.notes,
        tx_hash: 'SIMULATED_TX_ID',
        is_simulated: true
      });

      setGeneratedId(hash);
      setTxHash('SIMULATED_TX_ID'); // Not needed for explorer but kept for state consistency

      // Step D: Generate ZKP Proof (Instant Background)
      console.log("Generating Zero-Knowledge Proof...");
      try {
        const inputs = {
          doctor_wallet: addressToBigInt(stellarAddress),
          patient_wallet: addressToBigInt(formData.patientAddr),
          prescription_id: addressToBigInt(hash)
        };
        // Simulated proof for instant feel
