      } catch (zkpErr) { }

      const isInPendingList = pendingAppointments.includes(formData.patientAddr);
      if (isInPendingList || isFromPending) {
          await dbService.completeAppointment(formData.patientAddr, stellarAddress);
          fetchPendingAppointments();
