        setSyncStep('confirmed');
        setBookingSuccess(true);
        setIsAccessGranted(true);
        setAppointmentData({ ...appointmentData, reason: '' });

        // If the error was caught but the service still returned a fallback hash
        if (err.hash) setLastTxHash(err.hash);

        await syncAccessList(stellarAddress); // Local fallback grant

        // Ensure it shows up in local state history
        await dbService.insertAppointment({
          patient_wallet: stellarAddress,
          doctor_wallet: AUTHORIZED_DOCTOR,
